import { catchAsync } from "utils/catchAsync";
import httpStatus from "http-status";
import ApiError from "utils/ApiError";
import { User } from "models";

const getPagination = (query) => {
  const page = Math.max(parseInt(query.page, 10) || 1, 1);
  const limit = Math.min(Math.max(parseInt(query.limit, 10) || 10, 1), 100);
  const skip = (page - 1) * limit;
  return { page, limit, skip };
};

const getSortDirection = (sort) => {
  const normalized = String(sort || "asc").toLowerCase();
  return normalized === "desc" ? -1 : 1;
};

const getUserDisplayName = (userDoc) =>
  userDoc?.name || userDoc?.email || String(userDoc?._id || "User");

export const fetchAllFriends = catchAsync(async (req, res) => {
  const userId = req.user.id;
  const { name, sort } = req.query;
  const { page, limit, skip } = getPagination(req.query);
  const sortDirection = getSortDirection(sort);
  const user = await User.findById(userId).select("friends");
  if (!user) {
    throw new ApiError(httpStatus.NOT_FOUND, "User not found");
  }

  const nameFilter = name ? { name: { $regex: name, $options: "i" } } : {};
  const [friends, totalResults] = await Promise.all([
    User.find({ _id: { $in: user.friends }, ...nameFilter })
      .select("_id name email")
      .sort({ name: sortDirection })
      .skip(skip)
      .limit(limit),
    User.countDocuments({ _id: { $in: user.friends }, ...nameFilter }),
  ]);

  return res.status(httpStatus.OK).json({
    friends,
    page,
    limit,
    totalPages: Math.ceil(totalResults / limit) || 0,
    totalResults,
  });
});
// Working
export const sendFriendRequest = catchAsync(async (req, res) => {
  const userId = req.user.id;
  const { friendId } = req.body;
  if (userId === friendId) {
    throw new ApiError(
      httpStatus.BAD_REQUEST,
      "You cannot send friend request to yourself",
    );
  }
  const [sender, receiver] = await Promise.all([
    User.findById(userId).select(
      "name friends outgoingFriendRequests incomingFriendRequests",
    ),
    User.findById(friendId).select(
      "name friends outgoingFriendRequests incomingFriendRequests",
    ),
  ]); 

  if (!sender || !receiver) {
    throw new ApiError(httpStatus.NOT_FOUND, "User not found");
  }

  if (sender.friends.some((id) => String(id) === friendId)) {
    throw new ApiError(httpStatus.BAD_REQUEST, "Users are already friends");
  }
  if (sender.outgoingFriendRequests.some((id) => String(id) === friendId)) {
    throw new ApiError(httpStatus.BAD_REQUEST, "Friend request already sent");
  }
  if (sender.incomingFriendRequests.some((id) => String(id) === friendId)) {
    throw new ApiError(
      httpStatus.BAD_REQUEST,
      "You already have an incoming request from this user. Please accept/reject it",
    );
  }

  await Promise.all([
    User.updateOne(
      { _id: userId },
      { $addToSet: { outgoingFriendRequests: friendId } },
    ),
    User.updateOne(
      { _id: friendId },
      { $addToSet: { incomingFriendRequests: userId } },
    ),
  ]);

  return res.status(httpStatus.CREATED).json({
    message: `${getUserDisplayName(sender)} sent the friend request to ${getUserDisplayName(receiver)} successfully`,
  });
});

export const friendRequest = catchAsync(async (req, res) => {
  const { id: requesterId } = req.params;
  const userId = req.user.id;
  const { action } = req.body;

  if (requesterId === userId) {
    throw new ApiError(
      httpStatus.BAD_REQUEST,
      "Requester and user cannot be the same",
    );
  }

  const [requester, receiver] = await Promise.all([
    User.findById(requesterId).select("name email outgoingFriendRequests friends"),
    User.findById(userId).select("name email incomingFriendRequests friends"),
  ]);

  if (!requester || !receiver) {
    throw new ApiError(httpStatus.NOT_FOUND, "User not found");
  }

  const isIncomingPending = receiver.incomingFriendRequests.some(
    (id) => String(id) === requesterId,
  );
  const isOutgoingPending = requester.outgoingFriendRequests.some(
    (id) => String(id) === userId,
  );
  if (!isIncomingPending || !isOutgoingPending) {
    throw new ApiError(
      httpStatus.NOT_FOUND,
      "Friend request not found or already processed",
    );
  }

  if (action === "accept") {
    await Promise.all([
      User.updateOne(
        { _id: userId },
        {
          $pull: { incomingFriendRequests: requesterId },
          $addToSet: { friends: requesterId },
        },
      ),
      User.updateOne(
        { _id: requesterId },
        {
          $pull: { outgoingFriendRequests: userId },
          $addToSet: { friends: userId },
        },
      ),
    ]);

    return res.status(httpStatus.OK).json({
      message: `${getUserDisplayName(receiver)} accepted friend request from ${getUserDisplayName(requester)}`,
    });
  }

  await Promise.all([
    User.updateOne(
      { _id: userId },
      { $pull: { incomingFriendRequests: requesterId } },
    ),
    User.updateOne(
      { _id: requesterId },
      { $pull: { outgoingFriendRequests: userId } },
    ),
  ]);

  return res.status(httpStatus.OK).json({
    message: `${getUserDisplayName(receiver)} rejected friend request from ${getUserDisplayName(requester)}`,
  });
});

export const getFriendRequestWithPagination = catchAsync(async (req, res) => {
  const userId = req.user.id;
  const { sort } = req.query;
  const { page, limit, skip } = getPagination(req.query);
  const sortDirection = getSortDirection(sort);

  const user = await User.findById(userId).select("incomingFriendRequests");
  if (!user) {
    throw new ApiError(httpStatus.NOT_FOUND, "User not found");
  }

  const [incomingRequests, totalResults] = await Promise.all([
    User.find({ _id: { $in: user.incomingFriendRequests } })
      .select("_id name email")
      .sort({ name: sortDirection })
      .skip(skip)
      .limit(limit),
    User.countDocuments({ _id: { $in: user.incomingFriendRequests } }),
  ]);

  return res.status(httpStatus.OK).json({
    incomingRequests,
    page,
    limit,
    totalPages: Math.ceil(totalResults / limit) || 0,
    totalResults,
  });
});
